"""Explain capacity, skip counters and post-store stop signals."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1945': ('출석표에는 전체 좌석 수, 건너뛸 사람 수, 실제 적은 사람 수를 따로 써요. 수집 상태도 서로 다른 숫자를 한데 묶어 관리해요.', 'size·skip·len의 차이와 지정 초기화의 0 규칙을 이해합니다.', '용량 3·skip 2에서 A·B는 건너뛰고 C·D·E를 저장하세요. len은 0·0·1·2·3으로 변해요.', ['stacktrace_cookie는 주소 수집에 필요한 상태를 모은 구조체예요. store는 저장할 배열의 주소, size는 배열 용량, skip은 앞으로 건너뛸 개수, len은 실제 저장한 개수예요. 여기서 cookie는 이 상태표를 뜻해요.', '코드의 .store=store처럼 멤버 이름을 지정하는 방식은 지정 초기화예요. 이 구조체 초기화 목록에서 .len을 쓰지 않았으므로 len은 0으로 초기화돼요. 단순히 초기화 없이 선언한 모든 지역 변수도 0이라는 뜻은 아니에요. 중괄호 초기화가 있다는 조건이 중요해요.', 'skip이 남아 있으면 주소를 저장하지 않고 skip만 하나 줄여요. 따라서 건너뛴 주소는 len에 포함되지 않아요. len은 관찰한 모든 주소의 수가 아니라 결과 배열에 넣은 수예요.', '용량 3·skip 2에 A·B·C·D·E를 순서대로 보낸다고 해요. A 뒤 skip 1·len 0, B 뒤 skip 0·len 0이에요. 이후 C·D·E를 저장하면서 len이 1·2·3이 돼요. 두 번의 건너뛰기가 배열 두 칸을 차지하지 않아요.', '유효한 결과는 0번부터 len-1번까지예요. store[0..len)이라는 표기는 왼쪽 0은 포함하고 오른쪽 len은 제외한다는 뜻이에요. len이 3이면 0·1·2번 칸을 읽고 3번 칸은 읽지 않아요.', '정상적으로 준비한 상태에서는 저장 때마다 len이 하나 늘고 size를 넘지 않도록 검사해요. 이 계속 지킬 조건을 불변식이라고 해요. skip과 len을 같은 숫자로 합치면 다음 저장 위치와 남은 건너뛰기 양을 따로 알 수 없게 돼요.'], [('중괄호 지정 초기화에서 쓰지 않은 cookie의 len은 어떤 값으로 시작하나요?', ['언제나 알 수 없는 임의 값이에요', '0이에요'], '정답은 두 번째예요. 이 구조체의 초기화 목록에서 생략한 멤버는 0으로 초기화돼요. 초기화 자체가 없는 지역 변수에까지 같은 규칙을 적용하지는 않아요.'), ('skip으로 주소 하나를 건너뛰면 len도 증가하나요?', ['아니요. 저장하지 않았으므로 그대로예요', '네. 본 주소는 전부 len으로 세요'], '정답은 첫 번째예요. skip은 앞으로 제외할 개수이고 len은 실제 결과 개수예요. 두 숫자가 세는 대상을 구별해야 해요.')]), 'os1946': ('빈 좌석이 하나도 없으면 접수 순서를 더 진행할 필요가 없어요. 이 함수도 저장 공간부터 확인하고 그다음 건너뛰기를 처리해요.', '용량 검사와 skip의 실행 순서, 포인터 유효성의 차이를 이해합니다.', 'size 0·len 0·skip 2에서 0>=0이 참이므로 false로 끝낸다고 표시하세요. skip은 2 그대로예요.', ['stack_trace_consume_entry는 주소 하나를 받을 때 실행하는 콜백이에요. 첫 조건은 len>=size예요. len은 이미 저장한 개수, size는 용량이므로 두 값이 같으면 빈 칸이 없다는 뜻이에요.', '이 첫 조건이 참이면 바로 false를 반환해요. false는 탐색을 더 진행하지 말라는 신호예요. 그 아래 skip 검사나 배열 저장 코드는 실행하지 않아요. return은 현재 함수의 실행을 그 자리에서 끝내요.', '용량 size=0, 저장 개수 len=0, skip=2를 넣으면 0>=0이 참이에요. skip을 1로 줄이기 전에 돌아가므로 skip은 2, len은 0으로 남아요. 배열의 첫 칸 store[0]도 쓰지 않아요.', '공간이 있고 skip이 양수일 때만 skip을 하나 줄이고 true를 반환해요. 예를 들어 size=3·len=0·skip=2이면 skip은 1로 줄어요. 용량이 있느냐에 따라 같은 skip 값이라도 실행 경로가 달라져요.', '이 검사는 숫자로 알려 준 범위를 넘지 않게 하는 검사예요. 실제 store 주소가 유효한 배열인지, 그 배열이 size만큼 긴지 전부 찾아서 확인하는 기능은 없어요. 네 칸 배열을 주면서 size=100이라고 거짓으로 알려도 함수가 실제 네 칸이라는 사실을 알아내지 못해요.', '호출한 쪽은 상태 구조체와 결과 배열이 유효하고 용량이 맞도록 준비해야 해요. 종이에서는 조건의 참·거짓과 바뀐 숫자만 따라가세요. 배열 접근을 생략하는 한 분기가 있다고 해서 임의의 잘못된 포인터를 언제나 안전하게 받는 함수라는 뜻은 아니에요.'], [('size 0·len 0·skip 2인 상태에서 이 콜백을 부르면 어떻게 되나요?', ['skip을 먼저 1로 줄이고 반드시 저장해요', 'skip은 2 그대로이고 false를 반환해요'], '정답은 두 번째예요. 첫 용량 조건에서 바로 돌아가요. 실행되지 않은 아래 문장은 skip이나 배열을 바꿀 수 없어요.'), ('이 콜백이 어떤 store 주소든 올바른 배열인지 검사하고 복구하나요?', ['아니요. 호출한 쪽이 유효한 배열과 맞는 용량을 줘야 해요', '네. 모든 포인터 오류를 자동으로 복구해요'], '정답은 첫 번째예요. len과 size 비교는 전달된 숫자 안의 경계 검사예요. 실제 메모리의 유효성과 크기를 검증하는 별도 기능은 아니에요.')]), 'os1947': ('마지막 빈 칸에 이름을 적고 나면 더 받을 자리가 없어요. 그만 받으라는 신호가 방금 적은 이름을 지우라는 뜻은 아니에요.', '후위 증가와 마지막 저장 뒤 false 반환을 구분합니다.', 'size 1·len 0·skip 0에 주소 10을 넣어 store[0]=10, len=1, 반환 false를 각각 적으세요.', ['앞의 용량 검사와 skip 검사를 통과하면 c->store[c->len++] = addr가 실행돼요. ->는 포인터가 가리키는 구조체의 멤버를 사용하는 표현이에요. store는 결과 배열이고 addr는 이번에 받은 주소예요.', 'len++는 후위 증가예요. 배열 번호에는 증가 전 len을 쓰고 len 자체는 하나 늘어나요. 이 문장이 끝난 다음 줄에서는 증가한 len을 보게 돼요. 그래서 len이 0이면 0번 칸을 사용하고 다음 줄에서는 len이 1이에요.', '다음 줄은 len<size를 반환해요. 값이 참이면 다음 주소를 받을 빈 칸이 있고, 거짓이면 더 받을 칸이 없다는 뜻이에요. 저장이 끝난 뒤 남은 공간을 묻는 검사예요.', '용량 1에 주소 10을 넣으면 store[0]에 10이 저장되고 len이 1이 돼요. 이어 1<1은 거짓이므로 false를 반환해요. 저장은 정상적으로 끝났고 중단 신호는 이후 탐색에 적용돼요.', 'false로 끝나는 길은 둘이에요. 처음부터 가득 차 첫 검사에서 끝나면 이번 주소를 쓰지 않아요. 반대로 마지막 칸을 방금 채워 끝나면 이번 주소가 들어 있어요. 반환값 하나만으로 두 경우를 같은 상황이라고 판단하면 안 돼요.', '탐색 담당자는 false를 받으면 다음 주소를 더 수집하지 않고, 호출한 쪽은 실제 저장 개수 len만큼 결과를 읽어요. false를 실패로 오해해 마지막 칸을 버리면 정상 수집한 주소를 하나 놓치게 돼요.'], [('용량 1의 마지막 칸에 주소를 저장한 콜백은 무엇을 반환하나요?', ['저장을 취소하고 true를 반환해요', '저장한 뒤 false를 반환해요'], '정답은 두 번째예요. 저장하고 len을 늘린 뒤 1<1을 검사하므로 false예요. 이 값은 더 진행하지 말라는 신호이며 이미 한 저장을 취소하지 않아요.'), ('콜백이 false를 반환하면 이번 주소는 언제나 저장되지 않았나요?', ['아니요. 마지막 칸에 저장하고 false가 될 수도 있어요', '네. false가 모든 배열 쓰기를 되돌려요'], '정답은 첫 번째예요. 처음부터 가득 찬 경우와 방금 가득 채운 경우를 나누어 봐요. 코드에는 false를 반환할 때 저장을 되돌리는 동작이 없어요.')]), 'os1948': ('특정 종류의 카드는 처음부터 목록에서 제외하고, 그 밖의 카드 중 처음 몇 장을 건너뛸 수 있어요. 종류 필터와 개수 건너뛰기는 서로 다른 단계예요.', '스케줄러 필터의 조기 반환과 일반 skip·용량 검사를 구분합니다.', 'S를 스케줄러 주소로 정하고 S·A·B에서 skip 1을 적용하세요. S는 필터, A는 skip, B는 저장이에요.', ['스케줄러는 어떤 태스크를 언제 실행할지 관리하는 커널 부분이에요. stack_trace_consume_entry_nosched는 스케줄러 함수에 속하는 주소를 결과에서 제외하는 콜백이에요. 주소가 그런 함수인지 in_sched_functions로 먼저 물어요.', '스케줄러 주소이면 바로 true를 반환해 다음 탐색을 계속하게 해요. 일반 stack_trace_consume_entry를 부르지 않으므로 skip을 줄이지 않고 len도 늘리지 않아요. true가 언제나 저장했다는 뜻은 아니라는 예예요.', '스케줄러 주소가 아니면 일반 콜백에 넘겨요. 그제야 용량을 검사하고, skip이 남았으면 줄이고, 저장할 차례이면 배열에 넣어요. 필터와 일반 수집의 순서를 바꾸면 결과가 달라질 수 있어요.', '용량 2·skip 1에서 합성 주소 S·A·B가 온다고 해요. S만 스케줄러 주소라고 정하면 S 뒤에도 skip은 1, A를 건너뛴 뒤 0, B를 저장한 뒤 len은 1이에요. 실제 커널 주소 분류를 실행한 예시가 아니라 두 단계를 나누어 보는 연습이에요.', '이 nosched 함수를 이미 가득 찬 상태로 스케줄러 주소에 대해 호출해도 첫 필터에서 true예요. 용량 검사는 일반 콜백 안에 있으므로 거기까지 가지 않아요. 같은 상태에서 일반 주소를 넘기면 용량 검사로 false가 돼요.', '다만 정상 탐색이 앞서 false를 받았다면 그때 중단해야 해요. 가득 찬 상태의 직접 호출 예시는 분기 순서를 비교하는 것이며 실제 walker가 중단 신호를 무시하고 계속 호출한다는 뜻은 아니에요. 어떤 콜백의 어느 조건이 먼저 실행되는지 구분해요.'], [('nosched가 제외한 스케줄러 주소도 skip을 하나 줄이나요?', ['네. 제외한 주소마다 skip을 줄여요', '아니요. 일반 콜백을 부르기 전에 돌아가요'], '정답은 두 번째예요. skip을 줄이는 코드는 일반 콜백 안에 있어요. 첫 필터에서 끝나면 그 코드는 실행되지 않아요.'), ('nosched에 가득 찬 상태와 스케줄러 주소를 직접 넘기면 무엇을 반환하나요?', ['필터에서 true로 건너뛰어요', '용량 때문에 반드시 false를 반환해요'], '정답은 첫 번째예요. 스케줄러 판별이 먼저라 일반 용량 검사에 도달하지 않아요. 이 결과와 walker가 이미 받은 중단 신호를 따라야 한다는 약속은 구별하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_482.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
